import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().runProgram();
    }

    void runProgram() {
        InputReader scanner = new InputReader(System.in);
        PrintWriter printer = new PrintWriter(System.out);

        final int MOD = 998244353;
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        int[] base = new int[10];
        for (int i = 0; i < k; i++) {
            base[scanner.nextInt()] = 1;
        }

        int[] result = new int[]{1};
        int exponent = n / 2;
        while (true) {
            if ((exponent & 1) == 1) {
                result = multiply(result, base, MOD);
            }
            exponent >>= 1;
            if (exponent == 0) break;
            base = multiply(base, base, MOD);
        }

        long sum = 0;
        for (int value : result) {
            sum = (sum + (long)value * value) % MOD;
        }
        printer.println(sum);
        printer.close();
    }

    int[] multiply(int[] first, int[] second, int mod) {
        int required = first.length + second.length - 1;
        int size = Math.max(2, Integer.highestOneBit(required - 1) << 1);

        double[] reA = new double[size];
        double[] imA = new double[size];
        for (int i = 0; i < first.length; i++) {
            long val = ((first[i] % mod) + mod) % mod;
            reA[i] = val & 0x7FFF;
            imA[i] = val >>> 15;
        }
        performFFT(reA, imA, false);

        double[] reB = new double[size];
        double[] imB = new double[size];
        for (int i = 0; i < second.length; i++) {
            long val = ((second[i] % mod) + mod) % mod;
            reB[i] = val & 0x7FFF;
            imB[i] = val >>> 15;
        }
        performFFT(reB, imB, false);

        double[] resRe = new double[size];
        double[] resIm = new double[size];
        double[] tmpRe = new double[size];
        double[] tmpIm = new double[size];

        for (int i = 0; i < size; i++) {
            int j = (size - i) & (size - 1);

            double a1r = (reA[i] + reA[j]) * 0.5;
            double a1i = (imA[i] - imA[j]) * 0.5;
            double a2r = (imA[i] + imA[j]) * 0.5;
            double a2i = (reA[j] - reA[i]) * 0.5;

            double b1r = (reB[i] + reB[j]) * 0.5;
            double b1i = (imB[i] - imB[j]) * 0.5;
            double b2r = (imB[i] + imB[j]) * 0.5;
            double b2i = (reB[j] - reB[i]) * 0.5;

            resRe[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
            resIm[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;
            tmpRe[i] = a1r * b2r - a1i * b2i + a2r * b1r - a2i * b1i;
            tmpIm[i] = a1r * b2i + a1i * b2r + a2r * b1i + a2i * b1r;
        }

        performFFT(resRe, resIm, true);
        performFFT(tmpRe, tmpIm, true);

        int[] output = new int[required];
        for (int i = 0; i < required; i++) {
            long aa = Math.round(resRe[i]);
            long bb = Math.round(tmpRe[i]);
            long cc = Math.round(resIm[i]);
            output[i] = (int)((aa + ((bb % mod) << 15) + ((cc % mod) << 30)) % mod);
        }
        return output;
    }

    void performFFT(double[] re, double[] im, boolean inverse) {
        int n = re.length;
        int bits = 32 - Integer.numberOfTrailingZeros(n);
        int[] rev = new int[n];
        for (int i = 1; i < n; i++) {
            rev[i] = (rev[i >> 1] >> 1) | ((i & 1) << (bits - 1));
        }

        for (int i = 1; i < n; i++) {
            if (i < rev[i]) {
                double temp = re[i];
                re[i] = re[rev[i]];
                re[rev[i]] = temp;
                temp = im[i];
                im[i] = im[rev[i]];
                im[rev[i]] = temp;
            }
        }

        for (int len = 2; len <= n; len <<= 1) {
            int half = len >> 1;
            double[] cosines = new double[half];
            double[] sines = new double[half];
            double sign = inverse ? -1 : 1;
            for (int i = 0; i < half; i++) {
                double angle = 2 * Math.PI * i / len * sign;
                cosines[i] = Math.cos(angle);
                sines[i] = Math.sin(angle);
            }

            for (int i = 0; i < n; i += len) {
                for (int j = 0; j < half; j++) {
                    double wR = cosines[j];
                    double wI = sines[j];
                    double uR = re[i + j];
                    double uI = im[i + j];
                    double vR = re[i + j + half] * wR - im[i + j + half] * wI;
                    double vI = re[i + j + half] * wI + im[i + j + half] * wR;

                    re[i + j] = uR + vR;
                    im[i + j] = uI + vI;
                    re[i + j + half] = uR - vR;
                    im[i + j + half] = uI - vI;
                }
            }
        }

        if (inverse) {
            for (int i = 0; i < n; i++) {
                re[i] /= n;
                im[i] /= n;
            }
        }
    }

    static class InputReader {
        private final InputStream inputStream;
        private final byte[] buffer = new byte[1024];
        private int index, count;

        public InputReader(InputStream inputStream) {
            this.inputStream = inputStream;
        }

        private int readNext() {
            if (count == -1) throw new RuntimeException();
            if (index >= count) {
                index = 0;
                try { count = inputStream.read(buffer); } catch (IOException e) { throw new RuntimeException(); }
                if (count <= 0) return -1;
            }
            return buffer[index++] & 0xFF;
        }

        public int nextInt() {
            int c = readNext();
            while (c <= 32) c = readNext();
            int sign = 1;
            if (c == '-') { sign = -1; c = readNext(); }
            int value = 0;
            do {
                if (c < '0' || c > '9') throw new RuntimeException();
                value = value * 10 + c - '0';
                c = readNext();
            } while (c > 32);
            return value * sign;
        }
    }
}
